import {THEMES,esc,enrich,thumbnailSvg,validateApp,hash} from './lib/catalog.mjs';
const $=s=>document.querySelector(s);
const storageKey='dreamcatcher-cinema-v1';
let stored={};try{stored=JSON.parse(localStorage.getItem(storageKey)||'{}');}catch{}
let saved=new Set(Array.isArray(stored.saved)?stored.saved.filter(x=>typeof x==='string'):[]);
let recent=Array.isArray(stored.recent)?stored.recent.filter(x=>typeof x==='string').slice(0,12):[];
let custom=[];for(const app of Array.isArray(stored.custom)?stored.custom.slice(0,50):[]){try{custom.push(enrich(app));}catch{}}
let cardSequence=0;
let apps=[],baseApps=[],view='gallery',filter='All apps',query='',toastTimer;
function persist(){try{localStorage.setItem(storageKey,JSON.stringify({saved:[...saved],recent,custom}));}catch{toast('Storage is unavailable. Changes will last for this visit.');}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2600);}
function imageSource(app){return app.thumbnailPath?`${app.thumbnailPath}?v=${app.captureRevision||app.revision}`:'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(thumbnailSvg(app));}
function card(app){const summaryId=`summary-${app.id}-${++cardSequence}`;const isSaved=saved.has(app.id);return `<article class="app-card"><div class="card-art"><img src="${esc(imageSource(app))}" alt="${esc(app.title)} — ${app.artworkSource==='captured-screenshot'?'app screenshot':'domain artwork'}" loading="lazy" width="800" height="450" data-fallback="${app.id}"><span class="art-type">${app.artworkSource==='captured-screenshot'?'App screenshot':app.artworkSource==='approved-screenshot'?'Screenshot':'Artwork fallback'}</span><button class="card-open" data-detail="${app.id}" aria-label="View ${esc(app.title)} details" aria-describedby="${summaryId}"></button><div class="card-preview"><p id="${summaryId}">${esc(app.summary)}</p></div><button class="card-save" data-save="${app.id}" aria-label="${isSaved?'Remove':'Save'} ${esc(app.title)} ${isSaved?'from':'to'} My List" aria-pressed="${isSaved}">${isSaved?'✓':'+'}</button></div><div class="card-meta"><h4 class="card-title">${esc(app.title)}</h4><span class="card-domain">${esc(app.domain)}</span></div></article>`;}
function shelf(title,caption,items,key){if(!items.length)return '';return `<section class="shelf" aria-label="${esc(title)}"><div class="shelf-head"><div><h3>${esc(title)}<span class="shelf-caption">${esc(caption)}</span></h3></div><div class="shelf-controls"><button data-scroll="${key}" data-dir="-1" aria-label="Scroll ${esc(title)} left">‹</button><button data-scroll="${key}" data-dir="1" aria-label="Scroll ${esc(title)} right">›</button></div></div><div class="rail" id="rail-${key}">${items.map(card).join('')}</div></section>`;}
function renderCatalog(){
  const matches=apps.filter(a=>(filter==='All apps'||a.domain===filter)&&[a.title,a.summary,a.owner,a.domain,...a.tags].join(' ').toLowerCase().includes(query.toLowerCase()));
  if(query||filter!=='All apps'){$('#shelves').innerHTML=matches.length?`<div class="shelf-head"><h3>${matches.length} ${matches.length===1?'app':'apps'} to explore</h3><button class="text-button" data-clear>Clear filters</button></div><div class="app-grid">${matches.map(card).join('')}</div>`:`<div class="empty"><h3>No apps in this orbit.</h3><p>Try a different name, purpose, or domain.</p><button class="secondary" data-clear>Clear filters</button></div>`;}
  else {const used=new Set(); const rows=[];const append=(title,caption,items,key)=>{const unique=items.filter(a=>!used.has(a.id));unique.forEach(a=>used.add(a.id));if(unique.length)rows.push(shelf(title,caption,unique,key));};append('In the spotlight','A few places to begin',apps.filter(a=>a.featured).concat(apps.find(a=>a.id==='quality-lens')||[]),'spotlight');append('Recently explored','Pick up where you left off',recent.map(id=>apps.find(a=>a.id===id)).filter(Boolean),'recent');append('Explore the collection','Find a tool for your next question',apps,'collection');$('#shelves').innerHTML=rows.join('');}
  $('#catalog-status').textContent='';updateCount();
}
function updateCount(){$('#list-count').textContent=[...saved].filter(id=>apps.some(a=>a.id===id)).length;}
function renderList(){const items=apps.filter(a=>saved.has(a.id));$('#saved-apps').innerHTML=items.length?items.map(card).join(''):`<div class="empty"><h3>A little space for your favorites.</h3><p>Use the + on any app to keep it here.</p><button class="primary" data-go-gallery>Explore apps</button></div>`;}
function toggleSave(id){if(!apps.some(a=>a.id===id))return;const add=!saved.has(id);add?saved.add(id):saved.delete(id);persist();updateCount();document.querySelectorAll(`[data-save="${id}"]`).forEach(b=>{const app=apps.find(a=>a.id===id);b.setAttribute('aria-pressed',String(add));b.setAttribute('aria-label',`${add?'Remove':'Save'} ${app.title} ${add?'from':'to'} My List`);b.textContent=b.classList.contains('card-save')?(add?'✓':'+'):(add?'✓ In My List':'+ My List');});if(view==='my-list')renderList();toast(add?'Added to My List':'Removed from My List');}
let dialogTrigger;
function showDialog(html){dialogTrigger=document.activeElement;$('#dialog-content').innerHTML=html;$('#detail-dialog').showModal();$('#detail-dialog').scrollTop=0;}
function closeButton(){return '<button class="dialog-close" data-close aria-label="Close details">×</button>';}
function detail(id){const a=apps.find(a=>a.id===id);if(!a)return;recent=[id,...recent.filter(i=>i!==id)].slice(0,12);persist();showDialog(`<div class="dialog-art"><img src="${esc(imageSource(a))}" alt="" data-fallback="${a.id}">${closeButton()}</div><div class="dialog-body"><div class="eyebrow">${esc(a.domain)} / APP PREVIEW</div><h2 id="dialog-title">${esc(a.title)}</h2><p>${esc(a.summary)}</p><div class="dialog-badges">${a.tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div><dl class="dialog-grid"><div><dt>Example owner</dt><dd>${esc(a.owner||'Not specified')}</dd></div><div><dt>Intended audience</dt><dd>${esc(a.audience||'Not specified')}</dd></div><div><dt>Description source</dt><dd>${a.descriptionSource==='owner'?'Owner approved':'App metadata · review suggested'}</dd></div><div><dt>Thumbnail</dt><dd>${a.artworkSource==='captured-screenshot'?`App screenshot · ${esc(a.capturedAt?.slice(0,10)||'captured')}`:a.artworkSource==='approved-screenshot'?'Approved screenshot':'Constellation artwork · capture pending'}</dd></div></dl><div class="dialog-actions"><button class="primary" disabled>App link not connected</button><button class="secondary" data-save="${a.id}" aria-pressed="${saved.has(a.id)}">${saved.has(a.id)?'✓ In My List':'+ My List'}</button></div><p class="disclaimer">Sample app metadata for this design preview. Internal applications, permissions, and live data are not connected.</p></div>`);}
const designRows=[
['Cinematic spotlight','Keep the Dreamcatcher constellation and two-line headline. Use a soft violet atmosphere, ample negative space, and a clear collection entry.'],
['Hover & focus','Lift 4px, scale 1.018×, sharpen a lilac outline. Reveal the purpose and My List action within the existing card footprint.'],
['App screenshots','Capture the actual app in a safe preview mode at 1440 × 810. Use a screenshot first; keep domain artwork as a labeled fallback.'],
['Rich collections','Horizontal shelves with a partial next card, swipe on touch, scroll buttons, and steady card dimensions.'],
['Detail reveal','Open a focused dialog with a larger screenshot, clear purpose, audience, owner, and app actions. Escape closes it.'],
['Personal shelf','My List keeps frequently needed apps together. This prototype saves on this device.'],
['Less visual noise','Metadata lives below artwork or inside details. No wall of badges, KPI cards, or flashing stars.'],
['Motion with restraint','180–300ms transitions, no autoplay. Reduced-motion settings remove transforms and transitions.'],
['Useful descriptions','Generate from task, subject, and audience. Keep owner-approved text. Never infer permissions, certification, or live metrics.']
];
function notes(){showDialog(`${closeButton()}<div class="notes-body"><div class="eyebrow">DREAMCATCHER / DESIGN DIRECTION</div><h2 id="dialog-title">The same universe.<br>A richer way to explore it.</h2><p>Streaming-style discovery translated into a useful app catalog. Hover timings and treatments here are proposed Dreamcatcher values, not measured HBO Max specifications.</p><table class="notes-table"><tbody>${designRows.map(r=>`<tr><th scope="row">${r[0]}</th><td>${r[1]}</td></tr>`).join('')}</tbody></table><p class="source-note">Reference: <a href="https://help.hbomax.com/us/Answer/Detail/000002559" target="_blank" rel="noopener noreferrer">HBO Max discovery, collections, and My List</a>.</p></div>`);}
function navigate(next,shouldScroll=true){view=['gallery','my-list','studio'].includes(next)?next:'gallery';$('.hero').hidden=view!=='gallery';for(const v of ['gallery','my-list','studio'])$(`#${v}-view`).hidden=v!==view;document.querySelectorAll('[data-nav]').forEach(b=>{if(b.dataset.nav===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});if(view==='my-list')renderList();if(view==='gallery'&&apps.length)renderCatalog();if(view==='studio')updateStudio();if(shouldScroll)window.scrollTo({top:0,behavior:'instant'});}
function go(next){if(location.hash===`#${next}`)navigate(next);else location.hash=next;}
function wire(){document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.nav)go(el.dataset.nav);if(el.dataset.detail)detail(el.dataset.detail);if(el.dataset.save)toggleSave(el.dataset.save);if(el.hasAttribute('data-close'))$('#detail-dialog').close();if(el.hasAttribute('data-clear')){query='';filter='All apps';$('#search').value='';renderFilters();renderCatalog();}if(el.hasAttribute('data-go-gallery'))go('gallery');if(el.dataset.filter){filter=el.dataset.filter;renderFilters();renderCatalog();}if(el.dataset.scroll){const rail=$(`#rail-${el.dataset.scroll}`);rail.scrollBy({left:Number(el.dataset.dir)*rail.clientWidth*.85,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}});
  document.addEventListener('error',e=>{if(e.target instanceof HTMLImageElement && e.target.dataset.fallback){const app=apps.find(a=>a.id===e.target.dataset.fallback);delete e.target.dataset.fallback;if(app){e.target.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(thumbnailSvg(app));e.target.alt=`${app.title} — artwork fallback`;const badge=e.target.parentElement.querySelector('.art-type');if(badge)badge.textContent='Artwork fallback';}}},true);
  $('#search').addEventListener('input',e=>{query=e.target.value;renderCatalog();});$('#explore').onclick=()=>$('#gallery-view').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});$('#design-notes').onclick=notes;$('#about').onclick=notes;
  $('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog'))$('#detail-dialog').close();});$('#detail-dialog').addEventListener('close',()=>{if(dialogTrigger?.isConnected)dialogTrigger.focus();});window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));
}
function renderFilters(){$('#filters').innerHTML=['All apps',...Object.keys(THEMES)].map(d=>`<button data-filter="${d}" aria-pressed="${d===filter}">${d}</button>`).join('');}
function studioData(){const form=new FormData($('#studio-form'));const title=String(form.get('title')||'Untitled app');const id='custom-'+hash(title);return enrich({id,title,domain:form.get('domain'),task:form.get('task'),subject:form.get('subject'),audience:form.get('audience'),tags:String(form.get('tags')||'').split(',').map(x=>x.trim()).filter(Boolean),owner:'App creator'});}
function updateStudio(){try{const app=studioData();$('#studio-art').src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(thumbnailSvg(app));$('#studio-art').alt=`${app.title} — generated domain artwork`;$('#studio-name').textContent=app.title;$('#studio-summary').textContent=app.summary;}catch{}}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);}
function wireStudio(){$('#studio-domain').innerHTML=Object.keys(THEMES).map(d=>`<option>${d}</option>`).join('');$('#studio-domain').value='Engineering';$('#studio-form').addEventListener('input',updateStudio);$('#studio-form').addEventListener('submit',e=>{e.preventDefault();try{const app=studioData();if(custom.length>=50&&!custom.some(a=>a.id===app.id))throw new Error('This preview supports 50 custom apps. Export metadata for a larger catalog.');custom=[app,...custom.filter(a=>a.id!==app.id)];apps=[...baseApps,...custom];persist();$('#studio-status').textContent=`${app.title} added. It is ready to explore in Discover.`;toast('Added to the sample catalog');}catch(error){$('#studio-status').textContent=error.message;}});$('#download-art').onclick=()=>{const app=studioData();download(thumbnailSvg(app),`${app.id}.svg`,'image/svg+xml');};$('#download-metadata').onclick=()=>{const app=validateApp(studioData());download(JSON.stringify(app,null,2),`${app.id}.json`,'application/json');};updateStudio();}
async function loadCatalog(){try{$('#catalog-status').textContent='Loading the collection…';const response=await fetch('catalog.json');if(!response.ok)throw new Error();const result=await response.json();if(!Array.isArray(result))throw new Error();baseApps=result.map(a=>{const base=enrich(a);const safePath=typeof a.thumbnailPath==='string'&&/^(thumbnails\/[a-z0-9-]+\.svg|screenshots\/[a-zA-Z0-9_-]+\.(png|webp|jpe?g))$/.test(a.thumbnailPath);return {...base,...(safePath?{thumbnailPath:a.thumbnailPath,artworkSource:a.artworkSource==='captured-screenshot'?'captured-screenshot':base.artworkSource,capturedAt:typeof a.capturedAt==='string'?a.capturedAt:'',captureRevision:typeof a.captureRevision==='string'?a.captureRevision:''}:{})};});apps=[...baseApps,...custom.filter(a=>!baseApps.some(b=>b.id===a.id))];renderCatalog();if(view==='my-list')renderList();}catch{$('#catalog-status').innerHTML='<div class="error-panel">The app catalog could not be loaded.<br><button class="secondary" id="retry">Try again</button></div>';$('#retry').onclick=loadCatalog;}}
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{Promise.resolve(context.registerTool({name:'search_dreamcatcher_apps',title:'Search Dreamcatcher apps',description:'Search the sample catalog and display matching apps.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:200}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input.query!=='string'||input.query.length>200)throw new Error('Provide a search query up to 200 characters.');query=input.query;filter='All apps';$('#search').value=query;renderFilters();go('gallery');renderCatalog();return apps.filter(a=>[a.title,a.summary,a.owner,...a.tags].join(' ').toLowerCase().includes(query.toLowerCase())).map(a=>({id:a.id,title:a.title,summary:a.summary}));}},{signal:lifecycle.signal})).catch(()=>{});}catch{}}
wire();renderFilters();wireStudio();navigate(location.hash.slice(1),false);await loadCatalog();registerTools();
